package pe.edu.upeu.pago.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*; import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<?> nf(ResourceNotFoundException e){return body(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(IllegalArgumentException e){return body(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(IllegalStateException.class) ResponseEntity<?> conflict(IllegalStateException e){return body(HttpStatus.CONFLICT,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> val(MethodArgumentNotValidException e){return body(HttpStatus.BAD_REQUEST,e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList().toString());} private ResponseEntity<?> body(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("timestamp",OffsetDateTime.now().toString(),"status",s.value(),"error",s.getReasonPhrase(),"message",m));}}